#include <stdio.h>

/* teste do desafio a-ficha-da-pessoa — counter_protocol (03-tdd 3.9.3).
   Fase SAIDA: a captura do stdout acontece DENTRO do teste (freopen para um
   arquivo temporario por cenario, chamada da funcao, leitura de volta). Os
   dois moldes sao declarados aqui com os MESMOS campos dos moldes do aluno, e
   cada cenario passa a sua pessoa. Duas pessoas diferentes: nenhuma linha fixa
   passa nos dois cenarios. */

typedef struct {
    int x;
    int y;
} Ponto;

typedef struct {
    char nome[40];
    Ponto casa;
} Pessoa;

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void aFichaDaPessoa(Pessoa p);

SM_TEST(a_ficha_da_ana) {
    Pessoa a = {"Ana", {3, 4}};

    freopen("sm_saida_1.tmp", "w", stdout);
    aFichaDaPessoa(a);
    fflush(stdout);

    FILE *f = fopen("sm_saida_1.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha da Ana", linha, "Ana mora em 3,4\n",
              "o nome sai do campo nome, e o 3 e o 4 saem dos campos da casa");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a ficha da pessoa e uma linha so: nenhuma linha extra e aceita");
    fclose(f);
}

SM_TEST(a_ficha_do_bruno) {
    Pessoa b = {"Bruno", {10, 0}};

    freopen("sm_saida_2.tmp", "w", stdout);
    aFichaDaPessoa(b);
    fflush(stdout);

    FILE *f = fopen("sm_saida_2.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha do Bruno", linha, "Bruno mora em 10,0\n",
              "trocando a ficha, a linha muda: o nome e os dois campos da casa dele");
    fclose(f);
}

solutionCode:
#include <stdio.h>

typedef struct {
    int x;
    int y;
} Ponto;

typedef struct {
    char nome[40];
    Ponto casa;
} Pessoa;

void aFichaDaPessoa(Pessoa p) {
    printf("%s mora em %d,%d\n", p.nome, p.casa.x, p.casa.y);
}
